#!/usr/bin/env python3
"""Sound effects for the English spot, generated by ElevenLabs (no synthesized placeholders).
Writes audio/en/sfx/<name>.mp3. Usage: python3 audio/en/bruitages_el.py [name ...]"""
import os, sys
from pathlib import Path
import requests

ICI = Path(__file__).resolve().parent
SONS = {
    "tap":      ("Soft modern smartphone screen tap, subtle and clean, very short UI click, no reverb", 0.5),
    "swish":    ("Quick airy swish for a clean screen transition, subtle, modern motion design", 0.6),
    "pop":      ("Soft rounded UI pop, gentle and warm, modern app notification bubble", 0.5),
    "marker":   ("Highlighter marker stroke across paper, one smooth swipe, close and dry", 1.2),
    "papier":   ("Sheet of paper sliding onto a desk, short and crisp", 0.7),
    "tampon":   ("Rubber stamp pressed hard onto paper on a wooden desk, single punchy thud", 0.6),
    "montee":   ("Soft airy reverse swell riser building tension, smooth, cinematic, ends abruptly", 2.6),
    "impact":   ("Deep cinematic whoosh into a soft warm low impact, clean modern logo reveal", 1.6),
    "scintille":("Bright soft shimmer of small chimes, short magical sparkle for a logo reveal", 1.5),
    "verrou":   ("Small digital lock click, secure confirmation sound, clean UI", 0.6),
    "frappe":   ("Light typing on a smartphone touch keyboard, a few soft taps", 1.2),
    "points":   ("Rapid sequence of tiny soft digital ticks, like dots lighting up one by one", 0.8),
}

def main(noms):
    dossier = ICI / "sfx"; dossier.mkdir(exist_ok=True)
    for nom in noms:
        texte, duree = SONS[nom]
        r = requests.post("https://api.elevenlabs.io/v1/sound-generation", params={"output_format": "mp3_44100_128"},
                          headers={"xi-api-key": os.environ["ELEVENLABS_API_KEY"], "Content-Type": "application/json"},
                          json={"text": texte, "duration_seconds": duree, "prompt_influence": 0.6}, timeout=180)
        if r.status_code != 200:
            print("✗", nom, r.status_code, r.text[:300]); continue
        (dossier / f"{nom}.mp3").write_bytes(r.content)
        print("✓", nom)

if __name__ == "__main__":
    main(sys.argv[1:] or list(SONS))
